const STORAGE_PREFIX='wlv.cim.review.v2.'; const ACTIVE_KEY='wlv.cim.activeSession.v2'; const IMAGE_DB='wlv-cim-image-cache-v1'; const IMAGE_STORE='images'; const MAX_IMPORT_JSON_BYTES=12*1024*1024;
