const descriptionDepthFrom=(row:Record<string,unknown>)=>looseField(row,['sampledepth','measureddepth','depth','md']);
const makeDescriptionFromRecord=(row:Record<string,any>,index:number,defaults?:Partial<Description>):Description=>{const point=descriptionDepthFrom(row);return{id:norm(row.description_id)||makeId(`description-${index}`),topDepth:norm(row.top_depth??row.topDepth)||point||defaults?.topDepth||'',baseDepth:norm(row.base_depth??row.baseDepth)||defaults?.baseDepth||'',text:descriptionTextFrom(row)||norm(row.text)||defaults?.text||'',category:'core_description',sourceType:(norm(row.source_type)==='integrated_source'?'integrated_source':norm(row.source_type)==='manual'?'manual':defaults?.sourceType||'external_addendum'),sourceFile:norm(row.source_file)||defaults?.sourceFile||'',sourceSheet:norm(row.source_sheet)||defaults?.sourceSheet||'',sourceRow:norm(row.source_row)||defaults?.sourceRow||'',sourceReference:norm(row.source_reference)||defaults?.sourceReference||'',confidence:norm(row.confidence)||defaults?.confidence||''}};
