const descriptionKey=(description:Description)=>[description.sourceFile||'',description.sourceSheet||'',description.sourceRow||'',description.topDepth||'',description.baseDepth||'',description.text||''].join('|').toLowerCase();
const dedupeDescriptions=(items:Description[])=>{const seen=new Set<string>();const output:Description[]=[];for(const item of items){if(!item.text)continue;const key=descriptionKey(item);if(seen.has(key))continue;seen.add(key);output.push(item)}return output};
const legacyWellDescriptions=(items:Segment[])=>dedupeDescriptions(items.flatMap(segment=>segment.descriptions??[]));
const stripSegmentDescriptions=(items:Segment[])=>items.map(segment=>({...segment,descriptions:[]}));
const descriptionMatchesSegment=(description:Description,segment:Segment)=>{const st=finiteDepth(segment.topDepth),sb=finiteDepth(segment.baseDepth),dt=finiteDepth(description.topDepth),db=finiteDepth(description.baseDepth);if(st===null||sb===null||dt===null)return false;const low=Math.min(st,sb),high=Math.max(st,sb);if(db===null||Math.abs(db-dt)<1e-9)return dt>=low-1e-9&&dt<high-1e-9;const dlow=Math.min(dt,db),dhigh=Math.max(dt,db);return dhigh>low+1e-9&&dlow<high-1e-9};
