const integrateWellDescriptionRecords=(records:Record<string,any>[],segments:Segment[],defaults?:Partial<Description>)=>{const descriptions=dedupeDescriptions(records.map((row,index)=>makeDescriptionFromRecord(row,index,defaults)).filter(description=>Boolean(description.text)));let covered=0;for(const description of descriptions){if(segments.some(segment=>isSourcePanel(segment)&&descriptionMatchesSegment(description,segment)))covered+=1}return{descriptions,covered,outside:descriptions.length-covered}};
const spreadsheetDescriptionRecords=(wb:XLSX.WorkBook,fileName:string)=>{const output:Record<string,any>[]=[];for(const sheetName of wb.SheetNames){const sheet=wb.Sheets[sheetName];const matrix=XLSX.utils.sheet_to_json<any[]>(sheet,{header:1,defval:'',raw:false});let headerIndex=-1,headers:string[]=[];for(let r=0;r<Math.min(matrix.length,40);r++){const candidate=(matrix[r]??[]).map(value=>norm(value));const normalized=candidate.map(value=>value.toLowerCase().replace(/[^a-z0-9]/g,''));const hasDescription=normalized.some(value=>['lithologicaldescription','lithologydescription','coredescription','description','lithology'].some(pattern=>value===pattern||value.startsWith(pattern)));const hasDepth=normalized.some(value=>['sampledepth','measureddepth','depth','md','topdepth'].some(pattern=>value===pattern||value.startsWith(pattern)));if(hasDescription&&hasDepth){headerIndex=r;headers=candidate;break}}if(headerIndex<0)continue;for(let r=headerIndex+1;r<matrix.length;r++){const values=matrix[r]??[];const row:Record<string,any>={};headers.forEach((header,c)=>{if(header)row[header]=values[c]??''});const description=descriptionTextFrom(row);const depth=descriptionDepthFrom(row)||valueFrom(row,'top_depth');if(!description||!depth)continue;row.source_file=fileName;row.source_sheet=sheetName;row.source_row=String(r+1);row.source_type='external_addendum';output.push(row)}}return output};
