const getImageBlob=async(key:string)=>{const db=await openImageDb();const blob=await new Promise<Blob|null>((resolve,reject)=>{const tx=db.transaction(IMAGE_STORE,'readonly');const request=tx.objectStore(IMAGE_STORE).get(key);request.onsuccess=()=>resolve(request.result instanceof Blob?request.result:null);request.onerror=()=>reject(request.error)});db.close();return blob};
