  const imageFiles=incoming.filter(file=>file.type.startsWith('image/'));const existingByName=new Map(segments.filter(segment=>segment.imageName).map(segment=>[normalizeFileName(segment.imageName),segment]));const updates=new Map<string,Partial<Segment>>();const created:Segment[]=[];let matched=0;
  for(const file of imageFiles){const existing=existingByName.get(normalizeFileName(file.name));const segment=existing??{...emptySegment(selectedWell?.depth_unit||'m'),name:file.name.replace(/\.[^.]+$/,''),source:file.name,imageName:file.name,mimeType:file.type};const assetKey=`${selectedWellId}:${segment.id}`;await putImageBlob(assetKey,file);const patch={imageAssetKey:assetKey,imageName:file.name,mimeType:file.type,imageDataUrl:''};if(existing){updates.set(existing.id,patch);matched+=1}else created.push({...segment,...patch})}
  const existingCount=fileObjects.length;const nextObjects=[...fileObjects,...incoming];fileObjectsRef.current=nextObjects;setFileObjects(nextObjects);setSupportingFiles(current=>[...current,...incoming.map(file=>({name:file.name,type:file.type,size:file.size}))]);if(updates.size||created.length)setSegments(current=>[...current.map(segment=>updates.has(segment.id)?{...segment,...updates.get(segment.id)!}:segment),...created]);
