   const managedAiRules=await fetchToolboxAiRules('CIM_JOIN');const combined={...managedAiRules.rules} as Record<string,unknown>;const profile=(combined.deterministic_screening&&typeof combined.deterministic_screening==='object'&&!Array.isArray(combined.deterministic_screening))?combined.deterministic_screening as Record<string,unknown>:{};const signature=JSON.stringify(profile);const nextResults={...supportingFilePreScanResults};const nextAudit={...supportingFileAuditResults};
